// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT, LogFile} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
        LogFile log = new LogFile();
        c.SetLogFile(address(log));
        c.Initialized();
    }

    function testFuzz_property(uint256 amount, address actor) public {
        amount = bound(amount, 1 ether, 10 ether);
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        Reenterer attacker = new Reenterer(address(c), amount);
        vm.deal(address(attacker), amount);

        vm.prank(address(attacker));
        c.Deposit{value: amount}();

        uint256 beforeBal = c.balances(address(attacker));
        assertTrue(beforeBal >= amount);

        vm.prank(address(attacker));
        (bool ok,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", amount));
        assertTrue(ok);

        uint256 afterBal = c.balances(address(attacker));
        assertTrue(afterBal == beforeBal - amount);
    }
}

contract Reenterer {
    address payable private target;
    uint256 private attackAmount;
    bool private entered;

    constructor(address _target, uint256 _attackAmount) {
        target = payable(_target);
        attackAmount = _attackAmount;
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            target.call(abi.encodeWithSignature("Collect(uint256)", attackAmount));
        }
    }
}
